// tools/list for both hosts (ADR 0034, section 5): the same tools with the same schemas.
#include "core_internal.hpp"

namespace bloom::mcp {

yyjson_mut_val* toolList(Json& out) {
    // Schemas describe transport arguments. Operation arguments themselves are discovered from
    // the host registry through query(kind="operations").
    constexpr std::string_view schemas =
        R"json({"tools":[
{"name":"query","description":"Read revisioned projections. Parameters support summary pages (pageSize/cursor), individual records (parameter), and UTF-8 string chunks (parameter-value with expectedRevision). kind=context returns the editor context contextual arguments fall back to (project, composition, selected nodes and layers, time, the Viewer's display and view, read-only state, and live). kind=layers and kind=keyframes read one composition's layers (with shy and nameFollowsSource) and animation keys (with interpolation, ease handles and easing parameters); kind=enums lists the interpolation, ease and Easy Ease vocabularies.","inputSchema":{"type":"object","properties":{"kind":{"type":"string","enum":["project","compositions","nodes","parameters","parameter","parameter-value","assets","operations","context","layers","keyframes","enums"]},"composition":{"type":"integer","minimum":1},"pageSize":{"type":"integer","minimum":1,"maximum":64},"cursor":{"type":"string","maxLength":160},"parameter":{"type":"integer","minimum":1},"expectedRevision":{"type":"integer","minimum":0},"offset":{"type":"integer","minimum":0},"limit":{"type":"integer","minimum":4,"maximum":131072}},"required":["kind"],"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"transact","description":"Execute an atomic operation list with an expected revision and one undo entry. In the desktop application it lands in the artist's undo history.","inputSchema":{"type":"object","properties":{"expectedRevision":{"type":"integer","minimum":0},"label":{"type":"string","maxLength":4096},"operations":{"type":"array","minItems":1,"items":{"type":"object","properties":{"op":{"type":"string"},"args":{"type":"object"}},"required":["op","args"],"additionalProperties":false}}},"required":["expectedRevision","operations"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"history","description":"Undo or redo one step of the project's history, guarded by the expected revision.","inputSchema":{"type":"object","properties":{"action":{"type":"string","enum":["undo","redo"]},"expectedRevision":{"type":"integer","minimum":0}},"required":["action","expectedRevision"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"events","description":"Poll revision-inclusive command events; use afterSequence to avoid duplicates. resetRequired means the cursor must start again (events were trimmed or the project was replaced).","inputSchema":{"type":"object","properties":{"sinceRevision":{"type":"integer","minimum":0},"afterSequence":{"type":"integer","minimum":0}},"required":["sinceRevision"],"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"render","description":"Publish a reference still frame or inclusive frame range; return paths and SHA-256 digests. Output keeps alpha: the composition background color is Viewer display only and is never composited into a render, like every export. Nothing is replaced silently: pass overwrite=replace to replace an existing file.","inputSchema":{"type":"object","properties":{"composition":{"type":"integer","minimum":1},"frame":{"type":"integer","minimum":0},"first":{"type":"integer","minimum":0},"last":{"type":"integer","minimum":0},"preset":{"type":"string","enum":["PngRgba8SrgbV1","FlatExrRgba32fLinRec709SceneV1","TiffRgba16SrgbV1"]},"destination":{"type":"string","minLength":1,"maxLength":4096},"overwrite":{"type":"string","enum":["ask","replace","refuse"]}},"required":["composition","preset","destination"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"export","description":"Publish a composition using MEDIA-4 image, ProRes preview, DNxHR or PCM presets. Worker capabilities remain platform dependent.","inputSchema":{"type":"object","properties":{"composition":{"type":"integer","minimum":1},"frame":{"type":"integer","minimum":0},"first":{"type":"integer","minimum":0},"last":{"type":"integer","minimum":0},"preset":{"type":"string","enum":["PngRgba8SrgbV1","FlatExrRgba32fLinRec709SceneV1","TiffRgba16SrgbV1","ProResMovV1","DnxhrMxfV1","PcmWavV1"]},"destination":{"type":"string","minLength":1,"maxLength":4096},"profile":{"type":"string","maxLength":32},"audio":{"type":"boolean"},"sampleRate":{"type":"integer","minimum":8000,"maximum":192000},"overwrite":{"type":"string","enum":["ask","replace","refuse"]}},"required":["composition","preset","destination"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"capture","description":"Render one PNG of a composition frame at composition resolution through the still export route and return it as an image (or a resource_link when it is too large to embed); it keeps alpha, without the composition background color. In the desktop application the result carries its transient job id and log. Defaults: the context composition at the context time, with the Viewer's display and view.","inputSchema":{"type":"object","properties":{"composition":{"type":"integer","minimum":1},"frame":{"type":"integer","minimum":0}},"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"export.start","description":"Start export queue jobs (the Export panel's Start).","inputSchema":{"type":"object","properties":{"jobs":{"type":"array","minItems":1,"maxItems":1024,"items":{"type":"integer","minimum":1}}},"required":["jobs"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"export.start-all","description":"Start every enabled export queue job.","inputSchema":{"type":"object","properties":{},"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"export.pause","description":"Pause a rendering export job at the next frame boundary.","inputSchema":{"type":"object","properties":{"job":{"type":"integer","minimum":1}},"required":["job"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"openWorldHint":false}},
{"name":"export.resume","description":"Resume a paused export job.","inputSchema":{"type":"object","properties":{"job":{"type":"integer","minimum":1}},"required":["job"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"openWorldHint":false}},
{"name":"export.stop","description":"Stop an export job.","inputSchema":{"type":"object","properties":{"job":{"type":"integer","minimum":1}},"required":["job"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"openWorldHint":false}},
{"name":"export.stop-all","description":"Stop every active export job.","inputSchema":{"type":"object","properties":{},"additionalProperties":false},"annotations":{"readOnlyHint":false,"openWorldHint":false}},
{"name":"export.retry","description":"Run a finished export job again.","inputSchema":{"type":"object","properties":{"job":{"type":"integer","minimum":1}},"required":["job"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"export.confirm-replace","description":"Confirm replacing an output's existing destination exactly as it was last checked.","inputSchema":{"type":"object","properties":{"job":{"type":"integer","minimum":1},"output":{"type":"integer","minimum":1}},"required":["job","output"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"export.status","description":"The export queue snapshot: jobs, states, progress, failures and verification, plus recentTransientJobs (the newest 32 finished render, export and capture jobs). With sinceRevision, an unchanged queue answers unchanged=true.","inputSchema":{"type":"object","properties":{"sinceRevision":{"type":"integer","minimum":0}},"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"export.events","description":"Terminal export events after a sequence.","inputSchema":{"type":"object","properties":{"afterSequence":{"type":"integer","minimum":0}},"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"export.log","description":"An export job's run log after a sequence. A finished render, export or capture job stays readable by its id (the newest 32).","inputSchema":{"type":"object","properties":{"job":{"type":"integer","minimum":1},"afterSequence":{"type":"integer","minimum":0}},"required":["job"],"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"export.wait","description":"Wait until an export job (or, without job, every active job) is finished, up to timeoutMs; reports progress when the request carries a progress token.","inputSchema":{"type":"object","properties":{"job":{"type":"integer","minimum":1},"timeoutMs":{"type":"integer","minimum":1,"maximum":86400000}},"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"export.presets","description":"The export presets available on this computer.","inputSchema":{"type":"object","properties":{},"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"export.script","description":"A script that recreates an export job and starts it (bloom-cli JSON or Python).","inputSchema":{"type":"object","properties":{"job":{"type":"integer","minimum":1},"format":{"type":"string","enum":["cli-json","python"]}},"required":["job"],"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
)json"
        // MSVC caps one literal piece at 16 KiB.
        R"json({"name":"project.save","description":"Save the open project to its file (File > Save). Not undoable; refused with bloom.mcp.no-path when the project has never been saved (use project.save-as), bloom.mcp.read-only for a read-only project. Records a project.saved event.","inputSchema":{"type":"object","properties":{},"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":false,"openWorldHint":false}},
{"name":"project.save-as","description":"Save the open project to an absolute .bloom path (File > Save As); the project then lives there. Refused with bloom.mcp.destination-exists unless replace is true, bloom.mcp.path-invalid for a relative path or a missing folder. Records a project.saved event.","inputSchema":{"type":"object","properties":{"path":{"type":"string","minLength":1,"maxLength":4096},"replace":{"type":"boolean"}},"required":["path"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"project.open","description":"Open the .bloom file at an absolute path, replacing the open project (File > Open). Refused with bloom.mcp.unsaved-changes unless discardChanges is true, and bloom.mcp.jobs-running while export jobs run unless stopJobs is true. Events cursors from the old project report resetRequired. Records a project.opened event.","inputSchema":{"type":"object","properties":{"path":{"type":"string","minLength":1,"maxLength":4096},"discardChanges":{"type":"boolean"},"stopJobs":{"type":"boolean"}},"required":["path"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"project.new","description":"Replace the open project with a new untitled one (File > New). Refused with bloom.mcp.unsaved-changes unless discardChanges is true, and bloom.mcp.jobs-running unless stopJobs is true. Records a project.created event.","inputSchema":{"type":"object","properties":{"discardChanges":{"type":"boolean"},"stopJobs":{"type":"boolean"}},"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"project.close","description":"Close the open project (File > Close); an empty project is shown. Refused with bloom.mcp.unsaved-changes unless discardChanges is true, and bloom.mcp.jobs-running unless stopJobs is true. Records a project.closed event.","inputSchema":{"type":"object","properties":{"discardChanges":{"type":"boolean"},"stopJobs":{"type":"boolean"}},"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"editor.reveal","description":"Desktop only: show a composition in the Viewer (making it the active composition) and optionally move the playhead. time is an integer whole frame of that composition at its frame rate, or [numerator, denominator] exact seconds. Never changes the project. bloom-mcp on stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"composition":{"type":"integer","minimum":1},"time":{"oneOf":[{"type":"integer"},{"type":"array","items":{"type":"integer"},"minItems":2,"maxItems":2}]}},"required":["composition"],"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"selection.set","description":"Desktop only: set, add to, remove from or clear the selected layers and nodes of a composition, as clicking in the Timeline or Nodes would; or the Select menus' all-layers, all-nodes, invert-layers, invert-nodes (of the active composition's selection), linked-upstream and linked-downstream (from nodes, or the selected nodes, through links and driver bindings). Operations with contextual layer or selection arguments then default to it. Never changes the project; stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"composition":{"type":"integer","minimum":1},"layers":{"type":"array","maxItems":4096,"items":{"type":"integer","minimum":1}},"nodes":{"type":"array","maxItems":4096,"items":{"type":"integer","minimum":1}},"mode":{"type":"string","enum":["set","add","remove","clear","all-layers","all-nodes","invert-layers","invert-nodes","linked-upstream","linked-downstream"]}},"required":["composition"],"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"composition.activate","description":"Desktop only: make a composition the active one (the Viewer, Timeline and contextual composition arguments follow it). Never changes the project; stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"composition":{"type":"integer","minimum":1}},"required":["composition"],"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"transport","description":"Desktop only: move or run the playhead. ram-preview caches the work area and then plays it, as the RAM Preview button and Numpad 0 do; stop also ends a RAM preview that is caching. seek needs time: an integer whole frame of the composition (default: the active one) at its frame rate, or [numerator, denominator] exact seconds. Never changes the project; stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"action":{"type":"string","enum":["seek","play","stop","step-forward","step-backward","go-to-start","go-to-end","ram-preview"]},"composition":{"type":"integer","minimum":1},"time":{"oneOf":[{"type":"integer"},{"type":"array","items":{"type":"integer"},"minItems":2,"maxItems":2}]}},"required":["action"],"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"viewer.set","description":"Desktop only: the Viewer's display settings, which never reach a render or the project: OCIO display and view (empty returns to the project default), exposure in stops, gamma (1.0 neutral), channel, zoom (\"fit\", \"actual-size\" or a factor where 1.0 is 100%), preview resolution, the look toggle, the surround background, the transparency grid, and the region of interest ({x, y, width, height} in composition pixels, clipped to the frame; null clears it). Only the given fields change. stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"display":{"type":"string","maxLength":256},"view":{"type":"string","maxLength":256},"exposure":{"type":"number","minimum":-64,"maximum":64},"gamma":{"type":"number","exclusiveMinimum":0,"maximum":10},"channel":{"type":"string","enum":["rgba","rgb","red","green","blue","alpha"]},"zoom":{"oneOf":[{"type":"string","enum":["fit","actual-size"]},{"type":"number","exclusiveMinimum":0,"maximum":64}]},"resolution":{"type":"string","enum":["auto","full","half","quarter"]},"look":{"type":"boolean"},"background":{"type":"string","enum":["solid","gray","black","white"]},"transparencyGrid":{"type":"boolean"},"regionOfInterest":{"oneOf":[{"type":"null"},{"type":"object","properties":{"x":{"type":"number"},"y":{"type":"number"},"width":{"type":"number","minimum":1},"height":{"type":"number","minimum":1}},"required":["x","y","width","height"],"additionalProperties":false}]}},"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"export.reveal","description":"Desktop only: bring the Export editor into view, as Jobs > Show in Export does (an open Export editor is focused; otherwise it takes the Timeline's panel, or a new panel along the bottom), and optionally select a job (export.status lists them). Queue edits never reveal it; call this when the artist should see the queue. Never changes the project or its undo history. bloom-mcp on stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"job":{"type":"integer","minimum":1}},"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"project.set-color-settings","description":"Project Settings > Color, as the dialog applies it: the project's OCIO configuration (config \"neutral\" = Bloom Neutral v1, \"aces\" = ACES 1.3 CG built-in, \"current\" = keep the project's own, the only choice for an external configuration) and its working color space (neutral: lin_rec709_scene, which reads \"Linear Rec.709 (sRGB)\"; aces: ACEScg, ACES2065-1, Linear Rec.709 (sRGB), Linear P3-D65 or Linear Rec.2020; omitted keeps the project's when the configuration stays, else the first). NOT undoable and not in the history: it marks the project dirty and changes how EVERY composition renders (working-space conversions, color pickers, exports); set it before authoring color. Returns code updated|no-change with the resulting config, workingSpace (the stored id) and workingSpaceLabel (the name the dialog shows); errors: invalid-config, invalid-settings (a working space the configuration does not offer), read-only, unavailable (the live application has not wired it yet, or no project).","inputSchema":{"type":"object","properties":{"config":{"type":"string","enum":["neutral","aces","current"]},"workingSpace":{"type":"string","maxLength":256}},"required":["config"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"idempotentHint":true,"openWorldHint":false}},
{"name":"profiler.snapshot","description":"Bloom's runtime telemetry now: memory (RSS, anonymous, per-pool host, pending and device bytes with ceilings and cumulative hits, misses, stores, evictions and refusals; host upload staging live and peak; admission claims; unattributed), GPU (Bloom's own allocations, the driver heap budget and usage, upload and readback bytes, submits), CPU per executor pool, tasks, stage timing histograms (log2 buckets from 16 us), playback and RAM Preview rates, and helper processes. Absent values are null, never 0; counters are cumulative, so rates come from two snapshots. snapshot.schemaVersion names the field set.","inputSchema":{"type":"object","properties":{},"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
)json"
        // MSVC caps one literal piece at 16 KiB.
        R"json({"name":"project.save-copy","description":"File > Save a Copy: write a byte-for-byte copy of a read-only project (a newer or preserved document, which Save cannot rewrite) to an absolute .bloom path; the open project stays where it is. Refused with bloom.mcp.invalid-argument for an editable project (use project.save-as), bloom.mcp.destination-exists unless replace is true, bloom.mcp.path-invalid for a relative path or a missing folder. Records a project.copy-saved event.","inputSchema":{"type":"object","properties":{"path":{"type":"string","minLength":1,"maxLength":4096},"replace":{"type":"boolean"}},"required":["path"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"project.cancel-open","description":"Desktop only: File > Cancel Open, abandoning the project open in progress (the artist's or an agent's); the project that was open stays. Refused with bloom.mcp.invalid-argument when nothing is opening. stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{},"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":false,"openWorldHint":false}},
{"name":"preferences.get","description":"Desktop only: the application preferences (Edit > Preferences) as {key: value}: playback, memory and media cache, timeline, node graph, Viewer defaults and guides, import defaults, sounds and notifications. Per-user settings, never project truth. stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{},"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"preferences.set","description":"Desktop only: change application preferences as the Preferences window's OK does: every entry is checked first (an unknown key or a value out of range refuses the whole call with bloom.mcp.invalid-argument naming the key), then all are saved and applied to the open editors together. preferences.get lists the keys and their current values. Not undoable and not in the project. Refused with bloom.mcp.busy while a modal dialog is open. stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"preferences":{"type":"object","minProperties":1,"maxProperties":64,"additionalProperties":{"type":["boolean","number","string"]}}},"required":["preferences"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":false,"openWorldHint":false}},
{"name":"cache.purge","description":"Desktop only: Edit > Purge. cache \"preview\" clears the RAM preview and operation caches; \"media\" clears the decoded media cache and its disk store (source files are never touched). Derived state only: the project, its revision and undo history are untouched. Refused with bloom.mcp.busy while a purge runs. stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"cache":{"type":"string","enum":["preview","media"]}},"required":["cache"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":false,"idempotentHint":true,"openWorldHint":false}},
{"name":"jobs.list","description":"Desktop only: the Jobs panel's rows (imports, previews, thumbnails, purges, export runs): id, name, phase, state, progress, whether it can be cancelled, and the export job of an export run. stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{},"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"jobs.cancel","description":"Desktop only: the Jobs panel's Cancel for one job (jobs.list ids): cooperative cancellation of a queued or running job. Refused with bloom.mcp.unknown-target for a job the panel does not list, and bloom.mcp.invalid-argument for a job that cannot be cancelled there (an export run: use export.stop). stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"job":{"type":"integer","minimum":1}},"required":["job"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},
{"name":"asset.reveal","description":"Desktop only: Reveal in File Manager for an asset: the platform's file manager selects the asset's file where it can, else opens its folder. Refused with bloom.mcp.unknown-target for an unknown asset and bloom.mcp.invalid-argument for an asset without a file (a font or a data asset). Never changes the project. stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"asset":{"type":"integer","minimum":1}},"required":["asset"],"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":true}},
{"name":"composition.presets","description":"Desktop only: the Composition Settings dialog's presets: the built-in sizes (size and pixel aspect only) and the artist's saved presets (also frame rate, duration, start timecode, drop-frame and background). Apply one with the bloom.composition.set-settings operation. stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{},"additionalProperties":false},"annotations":{"readOnlyHint":true,"openWorldHint":false}},
{"name":"composition.save-preset","description":"Desktop only: Save as preset in Composition Settings: save a composition's size, pixel aspect, frame rate, duration, start timecode, drop-frame and background under a new name. A per-user setting, never project truth or undo. Refused with bloom.mcp.invalid-argument for an empty name or one already used, bloom.mcp.unknown-target for an unknown composition. stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"composition":{"type":"integer","minimum":1},"name":{"type":"string","minLength":1,"maxLength":256}},"required":["composition","name"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":false,"openWorldHint":false}},
{"name":"composition.rename-preset","description":"Desktop only: Rename preset in Composition Settings, for a saved (not built-in) preset. Refused with bloom.mcp.unknown-target when no saved preset has that name, bloom.mcp.invalid-argument for an empty or used new name. stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":256},"newName":{"type":"string","minLength":1,"maxLength":256}},"required":["name","newName"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":false,"openWorldHint":false}},
{"name":"composition.delete-preset","description":"Desktop only: Delete preset in Composition Settings, for a saved preset. It is a per-user setting, so Undo cannot restore it (the dialog asks first; an agent call is the confirmation). Refused with bloom.mcp.unknown-target when no saved preset has that name. stdio answers bloom.mcp.not-live.","inputSchema":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":256}},"required":["name"],"additionalProperties":false},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}}
]})json";
    Parsed parsed(schemas);
    return out.copy(parsed.root());
}

} // namespace bloom::mcp
